select jsonb_pretty(jsonb_build_object(
 'tablas', (select jsonb_agg(jsonb_build_object('t',relname,'rls',relrowsecurity,'rls_forzada',relforcerowsecurity) order by relname) from pg_class where relnamespace='public'::regnamespace and relname in ('cardiolink_document_verifications','cardiolink_document_verification_events')),
 'privilegios_tablas_cliente', (select coalesce(jsonb_agg(jsonb_build_object('tabla',table_name,'rol',grantee,'priv',privilege_type)),'[]'::jsonb) from information_schema.role_table_grants where table_schema='public' and table_name in ('cardiolink_document_verifications','cardiolink_document_verification_events') and grantee in ('anon','authenticated','PUBLIC')),
 'ejecucion_funciones', (select jsonb_agg(jsonb_build_object('f',p.proname,'anon',has_function_privilege('anon',p.oid,'execute'),'authenticated',has_function_privilege('authenticated',p.oid,'execute'),'service_role',has_function_privilege('service_role',p.oid,'execute'),'definer',p.prosecdef,'search_path_fijo',coalesce(array_to_string(p.proconfig,',') like '%search_path=pg_catalog, public%',false)) order by p.proname) from pg_proc p where p.pronamespace='public'::regnamespace and (p.proname like 'cardiolink\_verificacion\_%' or p.proname in ('cardiolink_es_profesional_propio_v1','cardiolink_doc_verif_guard_v1','cardiolink_doc_verif_events_guard_v1'))),
 'triggers', (select jsonb_agg(jsonb_build_object('tabla',tgrelid::regclass::text,'t',tgname,'habilitado',tgenabled)) from pg_trigger where tgrelid in ('public.cardiolink_document_verifications'::regclass,'public.cardiolink_document_verification_events'::regclass) and not tgisinternal),
 'secuencias_cliente', jsonb_build_object('issue_seq_authenticated',has_sequence_privilege('authenticated','public.cardiolink_doc_verif_issue_seq','usage'),'events_seq_anon',has_sequence_privilege('anon','public.cardiolink_document_verification_events_id_seq','usage')),
 'filas', jsonb_build_object('verificaciones',(select count(*) from public.cardiolink_document_verifications),'eventos',(select count(*) from public.cardiolink_document_verification_events)),
 'documentos_total', (select count(*) from public.cardiolink_patient_documents),
 'documentos_de_prueba_residuales', (select count(*) from public.cardiolink_patient_documents where patient_id='__qa_v2a__')
)) as check_posterior;
